# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-gated target confirmation, hysteretic reacquisition, and
    corridor-aware proportional steering to approach the visible target with
    fewer unnecessary instruction changes.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")

    visible = bool(observation.get("target_visible", False))
    bearing = float(observation.get("target_bearing", 0.0))
    distance = observation.get("target_distance_class", "far")
    target_confidence = float(observation.get("target_confidence", 0.0))
    identity_confidence = float(observation.get("target_identity_confidence", 0.0))
    track_age = int(observation.get("track_age", 0))
    lost_steps = int(observation.get("lost_steps", 0))
    safety_confidence = float(observation.get("safety_confidence", 0.0))
    closing_risk = float(observation.get("closing_risk", 1.0))
    heading_error = abs(float(observation.get("heading_error", 180.0)))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            memory["state"] = "REACQUIRE"
        action = scan_direction
        memory["scan_direction"] = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        memory["last_action"] = action
        memory["state"] = "SEARCH"
        return action, 0.75, memory

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    # Near-target arrival remains conservative and requires alignment.
    if distance == "near":
        if heading_error <= 15.0 and abs(bearing) <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        if abs(bearing) <= 8.0 and observation.get("corridor_center", False):
            return emit("SLOW_DOWN", 0.86, "APPROACH")
        action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return emit(action, 0.88, "APPROACH")

    # Use a wider center deadband to avoid needless zig-zagging.
    if abs(bearing) <= 10.0 and observation.get("corridor_center", False):
        return emit("FORWARD", 0.92, "APPROACH")

    if bearing < -10.0 and observation.get("corridor_left", False):
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing > 10.0 and observation.get("corridor_right", False):
        return emit("VEER_RIGHT", 0.90, "APPROACH")

    # When the preferred side is unavailable, preserve a centered course.
    if observation.get("corridor_center", False):
        return emit("FORWARD", 0.88, "APPROACH")
    if observation.get("corridor_left", False):
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if observation.get("corridor_right", False):
        return emit("VEER_RIGHT", 0.82, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
